// These are AI-use exercises with trade-specific context, not technical
// qualification tests. Replace the illustrative evidence with site-approved
// documents and examples before using them for operational training.
const choice = (text, correct, feedback) => ({ text, correct, feedback });

function legacyAiQuestions(lab) {
  const { trade, scenario, evidence, risk, verification, goodHandoff, sensitive } = lab;
  const contextPrompt = (text) => `For this ${trade} scenario—${scenario}—${text}`;
  const stages = [
    { name: 'Intake & scope', situation: `A new ${trade} request has arrived and the information is incomplete. The learner must decide what the request actually asks for before using AI.` },
    { name: 'Source review', situation: `The learner has a sanitized note, manual excerpt, or approved procedure and needs AI to retrieve and organize relevant information without inventing missing details.` },
    { name: 'Draft & critique', situation: `AI has produced a polished draft from rough notes. The learner must find assumptions, unsupported claims, and missing context before the draft is shared.` },
    { name: 'Handoff', situation: `Another role or shift needs the result. The learner must decide what the recipient needs, what should be removed, and what requires human approval.` },
  ];
  const questions = [
    { prompt: contextPrompt('what is the best first prompt?'), choices: [
      choice(`“Fix this ${trade} problem.”`, false, 'Too vague. AI needs a defined task and the evidence you want it to use.'),
      choice(`“Turn this sanitized request into a draft work order with fields for location, problem, observed facts, missing information, and the next human check. Use only the attached evidence.”`, true, 'Correct. This asks AI for a useful workplace draft with clear limits.'),
      choice('“Tell me everything an expert would know.”', false, 'That invites broad, unsupported content rather than a reviewable answer.'),
    ]},
    { prompt: contextPrompt('what context should you add before asking AI for help?'), choices: [
      choice('The location or asset, requester words, date and time, approved source, intended audience, and any names or access details to remove.', true, 'Correct. Those details make the output usable while reducing unnecessary exposure.'),
      choice('Only the desired conclusion.', false, 'That can bias the answer and hide uncertainty.'),
      choice('Every document in the department, whether relevant or not.', false, 'More context is not always better; irrelevant material creates noise.'),
    ]},
    { prompt: contextPrompt('how should AI treat the evidence pack?'), choices: [
      choice('Ask AI to pull out the relevant passage or section reference, then check that passage before using the answer.', true, 'Correct. This turns a document search into a checkable workplace result.'),
      choice('As optional background if AI already knows the topic.', false, 'The training task is to use the supplied evidence, not generic memory.'),
      choice('As permission to fill in missing values with typical industry numbers.', false, 'Typical values can be wrong for the actual site or equipment.'),
    ]},
    { prompt: contextPrompt('AI gives a confident answer that is not supported by the evidence. What should you do?'), choices: [
      choice('Accept it because the wording is confident.', false, 'Confidence is not verification.'),
      choice('Ask AI to show the supporting fact, name the missing evidence, and rewrite the claim as unconfirmed.', true, 'Correct. That creates a usable correction instead of accepting a polished guess.'),
      choice('Delete the source so AI can reason freely.', false, 'Removing evidence makes review harder, not safer.'),
    ]},
    { prompt: contextPrompt('which follow-up question improves the answer most?'), choices: [
      choice(`“Turn the verified facts into a short note for the next person. List what is still unknown and the next safe check.”`, true, 'Correct. It produces a practical handoff without pretending the work is complete.'),
      choice('“Can you make that sound more certain?”', false, 'More certainty without more evidence is a quality problem.'),
      choice('“What would you do if you were physically here?”', false, 'AI is not physically inspecting the site and should not pretend it is.'),
    ]},
    { prompt: contextPrompt('which AI output needs the most correction?'), choices: [
      choice(`“${lab.badClaim}” with no source, reading, or verification step.`, true, 'Correct. A polished unsupported cause should be challenged and rewritten.'),
      choice('“Here are the observations copied from the note.”', false, 'That can be useful if the copy is accurate.'),
      choice('“These are the questions I would ask the responsible trade.”', false, 'Question generation is an appropriate AI task.'),
    ]},
    { prompt: contextPrompt('what is the correct safety boundary?'), choices: [
      choice('AI may replace the site procedure if its answer seems reasonable.', false, 'AI does not replace approved procedures, authorization, or qualified judgment.'),
      choice(`Use AI to prepare a checklist or draft, but follow the approved procedure and escalate ${risk}.`, true, 'Correct. AI supports the workflow; it does not authorize hazardous work.'),
      choice('Avoid documenting the risk so the work order stays simple.', false, 'Risk context belongs in a responsible handoff.'),
    ]},
    { prompt: contextPrompt('which information should you remove or protect before sending it to an AI tool?'), choices: [
      choice(`Remove or protect ${sensitive} unless the organization has approved that tool and data path.`, true, 'Correct. Minimize sensitive data before using AI or sharing the draft.'),
      choice('Nothing; work information is never sensitive.', false, 'Facilities data can include personal, security, operational, or commercial information.'),
      choice('The evidence source, because citations are private.', false, 'Source provenance is valuable; protect sensitive content rather than deleting accountability.'),
    ]},
    { prompt: contextPrompt('what should the final AI-assisted handoff contain?'), choices: [
      choice(goodHandoff, true, 'Correct. Those fields make the handoff useful to the next person.'),
      choice('Only the AI-generated recommendation.', false, 'The next person needs the evidence and uncertainty, not just a conclusion.'),
      choice('A statement that AI was right.', false, 'AI is a tool; the handoff should describe the work and evidence.'),
    ]},
    { prompt: contextPrompt('what is the strongest reflection after completing the task?'), choices: [
      choice(`“I will compare time saved with quality and risk, and revise or stop the pilot if unsupported claims continue.”`, true, 'Correct. A pilot decision needs a measure and a stop condition, not just a faster draft.'),
      choice('“AI saved time, so review was unnecessary.”', false, 'Time saved is not a substitute for review.'),
      choice('“The best prompt is the longest prompt.”', false, 'The best prompt is clear, scoped, and grounded in relevant evidence.'),
    ]},
  ];
  const realistic = {
    supervisor: [
      'A technician sends a draft work order after a warm-room complaint. It is polished, but the draft says “failed actuator” even though no actuator test was recorded.',
      'The supervisor receives the technician’s field note, the AI draft, and a manufacturer sequence. The draft cites none of them.',
      'The technician asks whether the AI draft can be copied directly into the maintenance system before the end of the shift.',
      'A night-shift handoff must explain what was observed, what remains open, and who is responsible for the next check.',
      'After two weeks, the pilot saves five minutes per work order but reviewers are correcting unsupported causes in 20% of drafts.',
    ],
    hvac: [
      'A PM work order for AHU-3 says “unit ready for startup,” but the note has only one checkmark and no filter, damper, or condensate details.',
      'The technician has an approved startup checklist, a manufacturer IOM excerpt, and a photo of the unit nameplate with the serial number hidden.',
      'AI drafts a startup checklist and adds a “normal discharge temperature” that does not appear in the supplied manual.',
      'The next technician needs a short handoff before energizing the unit on the morning shift.',
      'A one-week pilot reduces documentation time, but reviewers find two invented readings in the sample.',
    ],
    bas: [
      'A service request says Conference Room 204 is warm. The BAS trend shows a 76°F zone, 72°F setpoint, 55°F supply air, and 100% damper command.',
      'The analyst has a trend export, point list, sequence of operation, and a note that the damper command is not proof of physical airflow.',
      'AI writes “failed actuator” in the first sentence even though no airflow reading or physical inspection is attached.',
      'The controls technician needs the next three checks in a clear handoff, not a replacement-parts recommendation.',
      'A pilot makes trend summaries faster, but reviewers report that the AI often treats commands as confirmed field conditions.',
    ],
    electrical: [
      'A caller reports that a receptacle circuit tripped twice after a portable heater was plugged in. A damp ceiling tile is visible nearby.',
      'The service center has the caller’s note and panel identifier, but no load inventory or authorized electrical test record.',
      'AI suggests resetting the breaker again to see whether the problem clears.',
      'The electrical supervisor needs a safe escalation note that does not authorize panel work by an unqualified person.',
      'The pilot improves report completeness, but one draft exposed a panel schedule and room access details unnecessarily.',
    ],
    plumbing: [
      'A tenant reports water near a ceiling light after heavy rain. The nearest restroom is one floor above and a roof drain is nearby.',
      'The work-control desk has the room number, time, weather, and a photo, but no confirmed source and no moisture reading.',
      'AI labels the problem “clogged roof drain” because the roof drain is the closest item in the note.',
      'The next shift needs to know what was protected, what was documented, and which trade must investigate.',
      'A pilot speeds up incident notes, but reviewers find that the AI turns possible sources into confirmed causes.',
    ],
    lifeSafety: [
      'The fire panel shows one smoke-detector point offline in an occupied wing after ceiling work took place nearby.',
      'The facilities desk has the panel message, point label, time, and occupancy status, but no confirmed cause.',
      'AI recommends bypassing the point until the next scheduled inspection.',
      'The responsible person needs a concise impairment escalation with no unnecessary security layout information.',
      'A pilot improves notification speed, but reviewers find that some drafts omit the required impairment procedure.',
    ],
    envelope: [
      'A ceiling stain appears 12 feet south of a patched roof penetration after a west-wind storm. No moisture reading was taken.',
      'The inspector has photos, weather notes, a roof-zone label, and a fall-protection requirement for roof access.',
      'AI states that the patched penetration is definitely the water-entry point.',
      'The building manager needs a handoff that distinguishes observations from the next safe inspection step.',
      'A pilot makes inspection summaries faster, but reviewers find that location is being treated as proof of source.',
    ],
    iaq: [
      'Occupants say a training room smells stale in the afternoon. A wall sensor reads 1,250 ppm CO₂, but its accuracy is unverified.',
      'The coordinator has occupancy, time of day, filter date, and a complaint note, but no outdoor-air measurement or health assessment.',
      'AI drafts “the room is unsafe” from the single CO₂ reading.',
      'The custodial or IAQ lead needs a respectful handoff that records the complaint without making a health diagnosis.',
      'A pilot reduces summary time, but reviewers find that AI sometimes turns occupant comments into medical conclusions.',
    ],
    grounds: [
      'The irrigation controller logged 20 minutes for Zone 7, but turf along the south walk is dry and the valve box is full of water.',
      'The grounds team has the controller log, zone map, weather, and a note that no flow or head-coverage reading is attached.',
      'AI recommends doubling the runtime and concludes that the controller is broken.',
      'The next grounds shift needs a short plan to check delivery, coverage, and water use without wasting more water.',
      'A pilot speeds up irrigation reports, but reviewers find that command logs are being treated as proof of delivery.',
    ],
  };
  const scenarioDetails = realistic[lab.key] || stages.map((stage) => stage.situation);
  const detailedPrompts = [
    `Ask AI to clean up this request or note into a draft work order. Have it list the location, problem, facts, missing information, and next check.`,
    `Ask AI what information is missing and have it write three short questions for the requester or technician.`,
    `Give AI the approved note, manual section, or procedure. Ask it to build a short checklist for the next person and mark every item that still needs a field check.`,
    `AI made a guess about the cause. Ask: “What in the note supports that? What is missing? How should we word it if we are not sure?”`,
    `Ask AI to turn the checked facts into a short email, work-order update, or shift note. Tell it who will read it and what facts to include.`,
    `Ask AI to sort the draft into three groups: what we saw, what we think, and what a qualified person still needs to approve.`,
    `Ask AI to make a short review checklist for the supervisor or qualified person who must check the draft before it is used.`,
    `Ask AI to find and flag names, access details, security information, contract details, or other information that should not be shared.`,
    `Ask AI to make a handoff with five simple parts: what happened, what we checked, what we still do not know, who goes next, and when.`,
    `Ask AI to compare the old way with this small test. Have it show one useful measure, one reason to stop, and whether to keep, change, or stop the test.`,
  ];
  return questions.slice(0, 8).map((item, index) => {
    const stage = stages[Math.floor(index / 2)];
    const situation = scenarioDetails[Math.floor(index / 2)];
    return { ...item, stageName: stage.name, stageSituation: situation, prompt: detailedPrompts[index], evidence: `STAGE\n${situation}\n\nBASE EVIDENCE\n${evidence}\n\nSTAGE REVIEW FOCUS\nThe learner should use AI only for preparation and documentation, identify what is missing, and keep a human reviewer responsible for: ${verification}.` };
  });
}

// The active labs use short, job-centered practice. Each scene lasts two
// questions so learners repeatedly move from "ask AI for help" to "check and
// use the result" without turning the lab into a trade-theory exam.
function practicalQuestions(lab) {
  const scenes = {
    supervisor: [
      { title: 'Monday morning room complaint', scene: 'At 7:15 a.m., a classroom is warm before the first class. The ticket has the room, time, and occupant complaint, but no trend or recent field check.', facts: 'The supervisor wants the technician to arrive prepared, not spend the first ten minutes guessing.', asks: ['Write an AI prompt that turns this information into five useful questions for the requester or technician. Do not ask AI to diagnose the fault.', 'Write the short message you would send to the technician. Include the questions, what is known, and what must be checked in person.'] },
      { title: 'Reviewing an AI draft', scene: 'A technician used AI to prepare a draft update. It says “failed actuator,” but the note only says the room was warm and the damper command was 100%.', facts: 'The supervisor has the note, the AI draft, and the approved sequence. No physical damper check is recorded.', asks: ['Tell AI exactly how to compare the draft with the note and sequence. Ask it to mark facts, guesses, and missing checks.', 'Rewrite the update in your own words so it can be used safely. State what is known, what is not known, and the next check.'] },
      { title: 'Vendor meeting prep', scene: 'Two vendors are coming to discuss a controls service proposal. One proposal is longer, but neither clearly states response time, after-hours coverage, or what is included in the price.', facts: 'The supervisor has two sanitized proposals and twenty minutes to prepare the crew for the meeting.', asks: ['Write a prompt that asks AI to make a side-by-side comparison and a list of questions. Tell it not to choose the vendor or invent missing terms.', 'Give three questions you would take into the meeting and explain what document or person will answer each one.'] },
      { title: 'Coaching after a pilot', scene: 'After two weeks, the team is using AI to prepare routine drafts. It saves a few minutes, but reviewers find that some drafts turn possible causes into confirmed causes.', facts: 'The supervisor needs to coach the team without banning a useful tool.', asks: ['Ask AI to turn these pilot notes into a five-minute toolbox-talk outline with one good example and one bad example.', 'Write the rule you would give the team for using AI on a draft, plus the one check that must happen before the draft is shared.'] },
    ],
    hvac: [
      { title: 'Getting ready for a rooftop call', scene: 'A teacher reports that three rooms are warm after a weekend event. The request lists the rooms and time, but not whether the problem is constant or only during occupied hours.', facts: 'The technician has fifteen minutes before leaving the shop and wants a better plan for the visit.', asks: ['Write an AI prompt that creates a short pre-job checklist: questions to ask, records to pull, and observations to make. Keep it focused on preparation, not a diagnosis.', 'Choose the three most useful items from that checklist and explain why you would check them before changing anything.'] },
      { title: 'Using a manual without guessing', scene: 'The approved startup guide covers filter condition, access panels, fan rotation, outdoor-air damper movement, and the condensate trap. It does not give one universal discharge-temperature number.', facts: 'A draft from AI added a temperature target that is not in the guide.', asks: ['Write the prompt you would use to turn the startup guide into a short pre-start checklist. Tell AI to use only the guide and mark anything that still needs a field check.', 'Write the correction you would make to the draft. Say what the guide supports and what must be checked using the site procedure or a qualified person.'] },
      { title: 'Parts counter question', scene: 'A vendor sends a replacement motor quote with a model number, lead time, and price. The old nameplate photo is blurry and the quote does not show compatibility details.', facts: 'The crew needs to ask better questions before anyone orders a part.', asks: ['Ask AI to compare the quote with the readable facts in the photo and make a “confirmed / missing / ask vendor” list. Do not ask it to approve the part.', 'Write the three questions you would send to the vendor and the evidence you would attach to each question.'] },
      { title: 'Shift handoff after a callback', scene: 'Day shift checked a unit after a comfort complaint. They recorded the time, room temperature, and filter condition, but the complaint returned later in the afternoon.', facts: 'Night shift needs a clear next step, not a polished story about the whole work order.', asks: ['Write a prompt that turns the day-shift notes into a short handoff with checked facts, open questions, and the next observation to make.', 'Write the handoff in your own words. Include the time window that matters and avoid naming a failed part unless it was verified.'] },
    ],
    bas: [
      { title: 'BAS trend before a room visit', scene: 'Conference Room 204 is warm at 2 p.m. The trend shows 76°F zone temperature, a 72°F setpoint, 55°F supply air, and 100% damper command.', facts: 'A command on the screen does not prove the damper moved or that air reached the room.', asks: ['Write an AI prompt that turns the trend and complaint into a short field-check plan. Ask for measurements and observations, not a replacement-part answer.', 'List the first three things you would verify in the field and label each as a trend check, physical check, or conversation with the occupant.'] },
      { title: 'Making a trend useful', scene: 'The analyst has a one-day trend export and a sequence of operation. The export has gaps during the busiest hour.', facts: 'The goal is to help the controls technician decide what to look at next, not to prove a fault from an incomplete graph.', asks: ['Ask AI to point out the useful pattern, the missing data, and two follow-up questions. Tell it to quote the time range it used.', 'Write a plain-language note to the controls technician that separates what the trend shows from what still needs a field check.'] },
      { title: 'Preparing for a controls vendor call', scene: 'A vendor says a software change will fix several comfort complaints. The proposed change has no test plan or rollback step.', facts: 'The facilities team wants to understand the proposal before agreeing to a change.', asks: ['Write a prompt that makes AI extract the proposed change, expected result, test method, rollback plan, and unanswered questions from the proposal.', 'Write four questions you would ask the vendor before approving a test. Include who must approve the change.'] },
      { title: 'Explaining a BAS finding', scene: 'A department manager asks why a room is still warm. The BAS screen shows a command, but the technician has not yet confirmed the damper position or airflow.', facts: 'The manager needs an honest update that does not sound evasive or overconfident.', asks: ['Ask AI to draft a two-sentence update using only the supplied facts and a clear next step. Tell it to avoid naming a cause.', 'Rewrite the update in your own words so a nontechnical reader can understand what was checked and what happens next.'] },
    ],
    electrical: [
      { title: 'Triage before dispatch', scene: 'A portable heater was plugged in, a receptacle circuit tripped twice, and a damp ceiling tile is visible nearby. The caller wants someone sent immediately.', facts: 'The service desk has no load inventory or authorized test record.', asks: ['Write an AI prompt that produces the questions the service desk must ask and the information the qualified electrician needs. Keep it away from troubleshooting instructions for an unqualified caller.', 'Write the dispatch note in your own words. Include the water concern, what the caller should not do, and who needs to be involved.'] },
      { title: 'Checking a draft for unsafe advice', scene: 'AI suggested resetting the breaker again to see whether the problem clears.', facts: 'The situation includes possible moisture near electrical equipment and no qualified inspection has occurred.', asks: ['Tell AI how to review that suggestion against the safety facts. Ask it to identify the unsafe step and suggest a safer escalation message.', 'Write the message you would send to the caller or front desk. Do not give a reset, panel, or energized-work instruction.'] },
      { title: 'Preparing a panel schedule question', scene: 'A qualified electrician needs information from an old panel schedule, but the scanned copy has several unreadable circuit labels.', facts: 'The team wants to use AI to make the document easier to review without treating OCR as truth.', asks: ['Write a prompt that asks AI to extract only readable labels, mark uncertain text, and list what must be checked at the panel.', 'Write three verification checks you would require before anyone relies on the extracted schedule.'] },
      { title: 'Incident follow-up', scene: 'The electrician found heat damage at one receptacle and tagged the area for repair. The cause and extent of damage still need qualified evaluation.', facts: 'A manager wants a quick update for the affected department.', asks: ['Ask AI to draft a short department update from the verified facts. Tell it to avoid blame, diagnosis, and repair promises.', 'Write the final update in your own words and name the human decision still pending.'] },
    ],
    plumbing: [
      { title: 'Water near a ceiling light', scene: 'After heavy rain, water is reported near a ceiling light. A restroom is one floor above and a roof drain is nearby, but no source is confirmed.', facts: 'The room is occupied and the first priority is a safe, coordinated response.', asks: ['Write an AI prompt that creates a first-response checklist for the desk: questions, people to notify, information to capture, and items not to assume.', 'Write the handoff to the responding crew. Include the location, time, affected electrical fixture, protection already taken, and the unknown source.'] },
      { title: 'Separating clues from cause', scene: 'A note says the nearest roof drain is clogged. The note contains no roof inspection or flow check.', facts: 'The statement is a guess based on location, not a verified finding.', asks: ['Ask AI to sort the note into observed facts, possible explanations, and missing checks. Tell it not to choose the leak source.', 'Rewrite the note so it is useful to the next trade without turning the guess into a confirmed cause.'] },
      { title: 'Vendor quote for a repair', scene: 'A plumbing vendor sends a quote after a site visit. It lists “repair leak” but does not say where the leak was found, what access is needed, or what is excluded.', facts: 'The team needs a better scope conversation before scheduling the work.', asks: ['Write a prompt that compares the quote with the site notes and produces questions about location, access, assumptions, exclusions, and closeout evidence.', 'Write four questions you would send back to the vendor before approving the quote.'] },
      { title: 'Closeout and occupant message', scene: 'The leak area was dried and protected. The repair is scheduled, but the source investigation is not complete.', facts: 'The occupant needs a useful update without a promise that the problem can never return.', asks: ['Ask AI to draft an occupant update from these facts with a clear time window and contact path. Tell it to avoid claiming the source is fixed.', 'Write the final message in your own words. Include what was done today and what is still scheduled.'] },
    ],
    lifeSafety: [
      { title: 'Alarm point goes offline', scene: 'One smoke-detector point is offline in an occupied wing after ceiling work nearby. The panel message, point label, and time are known; the cause is not.', facts: 'The designated responsible person and impairment procedure control the response.', asks: ['Write an AI prompt that makes a notification and escalation checklist from the approved impairment procedure. Ask it to show the section reference for each step.', 'Write the escalation note in your own words. Include who was notified, what is known, what is not known, and the procedure status.'] },
      { title: 'Catching a bad AI shortcut', scene: 'AI recommends bypassing the point until the next scheduled inspection.', facts: 'That recommendation is not supported by the supplied procedure and could hide an impairment.', asks: ['Ask AI to compare the recommendation with the impairment procedure and list the exact conflict. Tell it to mark unsupported advice.', 'Write the correction you would give the person using the tool. State what AI may help prepare and what the responsible person must decide.'] },
      { title: 'Contractor coordination', scene: 'A ceiling contractor is scheduled to work near the affected area. The work plan does not say how fire-alarm protection or notification will be handled.', facts: 'The facilities team needs questions for the pre-work meeting, not a new fire-alarm procedure invented by AI.', asks: ['Write a prompt that turns the work plan and approved procedure into a meeting question list. Tell AI to flag missing approvals.', 'Write the five questions you would ask before work starts and identify who must answer each one.'] },
      { title: 'Occupant communication', scene: 'A department asks whether it is safe to hold a meeting in the affected wing. The team has not yet completed the impairment review.', facts: 'The response must be timely and must not make an authorization that belongs to the responsible person.', asks: ['Ask AI to draft a plain-language holding message that says what is being checked and who will provide the decision.', 'Write the final message in your own words. Avoid giving a yes/no safety decision unless it is already documented by the responsible person.'] },
    ],
    envelope: [
      { title: 'Roof leak report', scene: 'A ceiling stain is about twelve feet south of a patched roof penetration after a west-wind storm. No moisture reading was taken.', facts: 'The inspector has photos, weather notes, and a roof-zone label. Roof access requires the site fall-protection process.', asks: ['Write an AI prompt that creates a roof-inspection prep list from the notes. Ask it to separate observations from questions and include the access requirement.', 'Write the next-step handoff in your own words. State what can be checked safely and what the location does not prove.'] },
      { title: 'Photo review without overclaiming', scene: 'Photos show a stain, a patch, and a dry surface on the day of inspection. The photos do not show the full roof assembly or a moisture reading.', facts: 'The building manager wants to know whether the patch failed.', asks: ['Ask AI to label what each photo can and cannot establish and to list the missing evidence needed before making a repair recommendation.', 'Write a two-paragraph update that answers the manager honestly and gives a practical next step.'] },
      { title: 'Scope conversation with a roofer', scene: 'A roofer proposes resealing the patched penetration but does not explain how the repair area was confirmed or what closeout photos will show.', facts: 'The team wants to ask good questions before approving a spot repair.', asks: ['Write a prompt that compares the proposal with the inspection notes and creates questions about evidence, access, scope, warranty, and closeout.', 'Write the questions you would ask the roofer. Do not ask AI to select the repair.'] },
      { title: 'Storm follow-up', scene: 'Three buildings reported stains after the same storm. The notes use different names for roof zones, making the list hard to compare.', facts: 'The facilities manager needs a clean list of locations, evidence gaps, and owners for the next inspection round.', asks: ['Ask AI to make a comparison table from the sanitized notes. Tell it to preserve each source label and mark any location it cannot match.', 'Write the fields you would require in the final inspection list before assigning work.'] },
    ],
    iaq: [
      { title: 'Stale-air complaint', scene: 'People say a training room smells stale in the afternoon. A wall sensor reads 1,250 ppm CO₂, but its accuracy is unverified.', facts: 'The team has occupancy and time of day, but no outdoor-air measurement or health assessment.', asks: ['Write an AI prompt that turns the complaint into questions for the room user and a simple observation plan. Tell it not to make a health conclusion.', 'Write the note you would send to the IAQ lead. Separate the complaint, the reading, the data limitation, and the next check.'] },
      { title: 'Avoiding a health claim', scene: 'AI drafted: “The room is unsafe because the CO₂ is high.” The only reading is from the unverified wall sensor.', facts: 'The draft could alarm occupants and is not supported by the evidence pack.', asks: ['Ask AI to show which part of the draft is unsupported and rewrite it using cautious, plain language.', 'Write the replacement sentence in your own words and name the measurement or process that must happen before a conclusion.'] },
      { title: 'Custodial coordination', scene: 'The room has a recurring odor after afternoon classes. Custodial staff report that the trash is removed, but the note does not record cleaning products, filters, or ventilation status.', facts: 'The team needs a coordinated set of questions instead of sending each group a vague request.', asks: ['Write a prompt that makes AI create separate questions for custodial, HVAC, and the room user. Tell it to keep the questions respectful and specific.', 'Write one question for each group and explain what answer would help narrow the next step.'] },
      { title: 'Occupant update', scene: 'The team has scheduled a sensor check and an HVAC observation for the next afternoon. No health finding has been made.', facts: 'The room user wants to know whether the issue has been fixed.', asks: ['Ask AI to draft a short update that explains what is scheduled, what is not yet known, and how the room user can report a change.', 'Write the final update in your own words without promising a cause or health outcome.'] },
    ],
    grounds: [
      { title: 'Dry turf, wet valve box', scene: 'The controller logged twenty minutes for Zone 7. Turf along the south walk is dry, while the valve box is full of water.', facts: 'No flow or head-coverage reading is attached. The crew wants to avoid doubling runtime and wasting water.', asks: ['Write an AI prompt that creates a short field-check plan from the controller log, zone map, weather, and observation. Ask it to separate command from delivery.', 'Write the first three checks you would make and what result from each check would change the next step.'] },
      { title: 'Avoiding the wrong fix', scene: 'AI recommends doubling the runtime and says the controller is broken.', facts: 'The evidence shows a command, dry turf, and a wet valve box, but it does not establish the cause.', asks: ['Ask AI to mark the unsupported parts of the recommendation and suggest questions that would help distinguish valve, flow, coverage, or scheduling issues.', 'Write the corrected crew note in your own words. Do not name a failed component without a check.'] },
      { title: 'Water-use meeting', scene: 'The irrigation vendor says the system is running as programmed. The grounds lead has a water bill increase and several dry areas.', facts: 'The team needs to compare the program with field observations before requesting changes.', asks: ['Write a prompt that compares the schedule, weather, zone map, and observations and produces a list of questions for the vendor.', 'Write four vendor questions that connect a reported command to a field result or water-use measure.'] },
      { title: 'Shift handoff', scene: 'The day crew checked one valve box and photographed the dry area. The remaining zones have not been checked.', facts: 'The night or next-day crew needs a focused plan, not a claim that the whole system failed.', asks: ['Ask AI to turn the notes into a next-shift checklist with location, checks completed, checks open, and water-use concern.', 'Write the handoff in your own words and identify the one result that would make you stop changing the schedule and escalate.'] },
    ],
    fleet: [
      { title: 'Fault code before the road call', scene: 'A dump truck shows fault code E-47 before a morning route. The operator says it still starts, but the display photo does not show the make, model, or engine hours.', facts: 'The mechanic has ten minutes to prepare questions before pulling the truck into the bay. The OEM manual is the source of truth.', asks: ['Write the prompt you would use to have AI explain what information is missing and build a short intake checklist. Tell it not to guess the code meaning.', 'Write the three questions you would ask the operator and the mechanic before choosing a diagnostic step. Say what source or observation would verify each answer.'] },
      { title: 'Parts cross-check', scene: 'A parts counter suggests a replacement sensor based on a partial number from an old invoice. The number is missing two characters.', facts: 'The fleet crew wants to avoid ordering the wrong part and delaying the route.', asks: ['Ask AI to make a confirmed / unclear / ask-the-vendor list from the invoice, nameplate photo, and service history. Tell it to flag the missing characters.', 'Write the message you would send to the vendor. Include the information you would attach and the exact confirmation needed before ordering.'] },
      { title: 'Service history that helps', scene: 'Three vehicles have had similar cooling complaints, but the service notes use different names for the same component and do not always include outside temperature.', facts: 'The fleet lead wants to spot a pattern without treating inconsistent notes as proof of one failure.', asks: ['Write a prompt that asks AI to standardize the terms, show missing fields, and compare the three records. Tell it to preserve each original note.', 'Write the follow-up data you would collect on the next call and explain what pattern would be worth checking with the OEM manual.'] },
      { title: 'Return-to-service message', scene: 'A truck repair is complete, but the mechanic has not yet finished the required test drive and inspection. Operations is asking whether the truck can be assigned.', facts: 'The final release decision belongs to the qualified mechanic and fleet process.', asks: ['Ask AI to draft a short status message that says what is complete, what is still pending, and who makes the release decision.', 'Write the final message in your own words. Do not say the vehicle is ready until the required check is documented.'] },
    ],
    roads: [
      { title: 'Morning crew briefing', scene: 'A road crew is scheduled to patch three locations. The supervisor has the location list, weather forecast, traffic-control plan, and material quantities, but the crew has not reviewed them together.', facts: 'The briefing must help the crew start safely and catch missing information before trucks leave the yard.', asks: ['Write an AI prompt that turns the approved plan into a five-minute crew briefing with locations, sequence, materials, traffic-control questions, and stop conditions. Tell it not to create a new traffic-control layout.', 'Write the two questions you would ask the crew before departure and identify which approved document answers each question.'] },
      { title: 'Snow-route log check', scene: 'After a snow event, the route log has salt quantities, start and end times, and several handwritten changes. One route total does not match the truck’s load record.', facts: 'The public-works lead needs to find the discrepancy before the report is submitted.', asks: ['Ask AI to compare the two records, list the numbers that do not match, and mark what must be confirmed by the operator. Tell it not to repair the numbers.', 'Write the short question you would send to the operator and the one source you would use to close the discrepancy.'] },
      { title: 'Resident notice', scene: 'A resident reports a damaged sign near an intersection. The crew has a photo and location, but the replacement date is not set and the photo includes a house number.', facts: 'The response should be helpful without promising a date or sharing unnecessary personal or location details.', asks: ['Write a prompt that drafts a plain-language resident reply from the approved facts. Tell AI to remove the house number and avoid promising a completion date.', 'Write the final reply in your own words and state what a supervisor must verify before it is sent.'] },
      { title: 'Work-zone plan questions', scene: 'A contractor’s work-zone plan uses a different road name than the crew’s location list and does not clearly identify the detour contact.', facts: 'The agency must follow its approved traffic-control process; AI may only help prepare questions.', asks: ['Ask AI to compare the plan and location list and produce a list of mismatches and questions. Tell it not to approve the plan.', 'Write the questions you would take to the qualified traffic-control reviewer before work begins.'] },
    ],
    water: [
      { title: 'Operator log cleanup', scene: 'The day operator dictated a rough log with times, tank level, pump status, and two unclear readings. The next shift needs to understand what was observed and what needs follow-up.', facts: 'The operator’s original notes are the source. AI may organize them but must not fill in missing readings.', asks: ['Write a prompt that turns the dictation into a shift log with time, reading, equipment status, unclear items, and follow-up. Tell AI to mark missing values instead of guessing.', 'Write the handoff in your own words and identify the two readings the next operator must confirm against the approved SOP or instrument.'] },
      { title: 'SOP learning aid', scene: 'A new operator is learning the approved sampling SOP and asks for a one-page practice checklist before working with a trainer.', facts: 'The checklist is for learning only. The SOP and trainer control the actual process.', asks: ['Ask AI to make a short practice checklist from the SOP, using the same terms as the document and marking each item that requires trainer sign-off.', 'Write the sentence you would put at the top of the checklist so nobody mistakes it for permission to work alone.'] },
      { title: 'Regulatory draft review', scene: 'A draft monthly report has a clean format, but one sample date and one result were copied from the wrong row in the spreadsheet.', facts: 'The report is public-accountability work. The operator or supervisor must verify the source data before submission.', asks: ['Ask AI to compare the draft with the source table and make a list of mismatches, missing fields, and rows that need human review. Tell it not to correct values on its own.', 'Write the correction note you would attach for the supervisor. Include the source row and the person responsible for confirming it.'] },
      { title: 'Stop-condition practice', scene: 'Someone asks AI what chlorine feed setting should be used because the treated-water reading changed. The current SOP and operator-in-charge are available.', facts: 'A dosing change is a safety and compliance decision. AI can help prepare questions but cannot choose the setting.', asks: ['Write the safe response you would give the coworker. Use the approved stop condition and name the source or person who must decide.', 'Write three questions AI could help prepare for the operator-in-charge without recommending a new dosing value.'] },
    ],
  };
  const labScenes = scenes[lab.key] || [];
  return labScenes.flatMap((item, sceneIndex) => item.asks.map((prompt, questionInScene) => ({
    prompt,
    stageName: item.title,
    stageSituation: item.scene,
    evidence: `JOB SITUATION\n${item.scene}\n\nWHAT WE KNOW\n${item.facts}\n\nAI TASK\n${prompt}\n\nREVIEW FOCUS\nUse AI to prepare a useful next step, question list, comparison, checklist, or message. Keep the trade decision with the qualified person, use only the supplied facts, and label what still needs to be checked. Work the answer through: identify the task, try a small prompt, check the result against the source of truth or your own field knowledge, and keep only the corrected version as a reusable shop card. Before using the result, ask: Is this task appropriate for AI? Did I protect information? What could be wrong or missing? What source or qualified person did I check? Can I own the final result?`,
    scenarioIndex: sceneIndex,
    questionInScene,
  })));
}

